import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledEmptyState = styled.div({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  flexDirection: 'column',
  width: '100%',
  height: '100%',
});

export const StyledResourceAllocationCardsArea = styled.div({
  display: 'flex',
  alignItems: 'stretch',
  flexDirection: 'column',
  width: '100%',
});

export const StyledChartContent = styled.div({
  height: '270px',
  padding: ['0', theme.spacing['4'], theme.spacing['4']].join(' '),
});
